# SmartTimetable Pro - Grade 10 option-block model correction
# Windows PowerShell 5.1 compatible.
$ErrorActionPreference = "Stop"

$Backend = "C:\Projects\SmartTimetable\backend"
$ModelPath = Join-Path $Backend "apps\scheduling\engine\solver\model.py"
$BackupDir = Join-Path $Backend "audit_backups"

if (-not (Test-Path $ModelPath)) {
    throw "model.py was not found at $ModelPath"
}

if (-not (Test-Path $BackupDir)) {
    New-Item -ItemType Directory -Path $BackupDir -Force | Out-Null
}

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backupPath = Join-Path $BackupDir "model.py_before_grade10_option_fix_$stamp.py"
Copy-Item -LiteralPath $ModelPath -Destination $backupPath -Force

$encoded = @"

"@

$bytes = [Convert]::FromBase64String(($encoded -replace "\s", ""))
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($ModelPath, $utf8NoBom.GetString($bytes), $utf8NoBom)

Write-Host ""
Write-Host "MODEL REPLACED SUCCESSFULLY" -ForegroundColor Green
Write-Host "Backup: $backupPath"
Write-Host "Model:  $ModelPath"
Write-Host ""

Set-Location $Backend

$Python = "C:\Projects\SmartTimetable\.venv\Scripts\python.exe"
if (-not (Test-Path $Python)) {
    throw "Virtual-environment Python was not found at $Python"
}

Write-Host "=== PYTHON SYNTAX CHECK ===" -ForegroundColor Cyan
& $Python -m py_compile $ModelPath
if ($LASTEXITCODE -ne 0) { throw "Python syntax check failed." }

Write-Host ""
Write-Host "=== DJANGO CHECK ===" -ForegroundColor Cyan
& $Python manage.py check
if ($LASTEXITCODE -ne 0) { throw "Django check failed." }

Write-Host ""
Write-Host "=== DIAGNOSTIC TESTS ===" -ForegroundColor Cyan
& $Python -m pytest tests/scheduling/test_infeasibility_diagnostics.py -q
if ($LASTEXITCODE -ne 0) { throw "Diagnostic tests failed." }

Write-Host ""
Write-Host "=== FULL SCHEDULING TESTS ===" -ForegroundColor Cyan
& $Python -m pytest tests/scheduling -q
if ($LASTEXITCODE -ne 0) { throw "Scheduling tests failed." }

Write-Host ""
Write-Host "============================================================"
Write-Host "GRADE 10 OPTION-BLOCK MODEL FIX COMPLETED" -ForegroundColor Green
Write-Host "============================================================"
Write-Host "The model now treats each Grade 10 option block as 5 shared"
Write-Host "physical weekly lessons instead of requiring every alternative"
Write-Host "subject row to consume 5 physical lessons."
Write-Host ""
Write-Host "No migration was run and no database records were changed."
Write-Host "Backup: $backupPath"
